std::vector<uint32> BoostTalents::GetExtraSpells(uint32 classId, uint8 spec)
{
  if (classId == CLASS_WARRIOR && spec == 1)
  {
    return {674};
  }
  if (classId == CLASS_DEATH_KNIGHT && spec == 1)
  {
    return {674};
  }
  if (classId == CLASS_SHAMAN && spec == 1)
  {
    return {674};
  }
  return {};
}

void BoostTalents::ApplyTalents(Player *player, uint8 specialization)
{
  if (specialization > 2)
  {
    specialization = 0;
  }

  // Start from a clean slate; a level-80 then has its full talent points free.
  player->resetTalents(true);

  // Baseline abilities a build assumes (e.g. Dual Wield) but the class is not taught.
  for (uint32 spellId : GetExtraSpells(player->getClass(), specialization))
  {
    player->learnSpell(spellId, false);
  }

  // Picks are pre-sorted by tier, so prerequisites/tier minimums are satisfied as we go.
  for (auto const &pick : GetBuild(player->getClass(), specialization))
  {
    for (uint32 r = 0; r < pick.second; ++r)
    {
      player->LearnTalent(pick.first, r);
    }
  }

  player->SendTalentsInfoData(false);
}

